const r = await tools.exec_command({cmd:"python3 - "$STAMPED_DELIVERY_MANIFEST" "$STAMPED_JUDGE_TARGET" <<'PY'
import hashlib, json, os, stat, sys
m=json.load(open(sys.argv[1]))
root=sys.argv[2]
problems=[]
for e in m['entries']:
    p=e['path']
    if not p.startswith('content/workspace/'):
        continue
    rel=p[len('content/workspace/'):]
    full=os.path.join(root,rel)
    kind=e['kind']
    if kind=='directory':
        if not os.path.isdir(full): problems.append((rel,'missing-or-not-directory'))
        continue
    if not os.path.lexists(full):
        problems.append((rel,'missing')); continue
    st=os.lstat(full)
    if kind=='symlink':
        if not stat.S_ISLNK(st.st_mode): problems.append((rel,'kind-changed')); continue
        data=os.fsencode(os.readlink(full))
    elif kind=='file':
        if not stat.S_ISREG(st.st_mode): problems.append((rel,'kind-changed')); continue
        if rel in {'.git/annex/keysdb/db','.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal'}:
            continue
        with open(full,'rb') as f: data=f.read()
    else:
        problems.append((rel,'unknown-manifest-kind:'+kind)); continue
    if len(data)!=e.get('size',len(data)) or hashlib.sha256(data).hexdigest()!=e.get('sha256'):
        problems.append((rel,'content-mismatch'))
print(json.dumps({'manifest_entries':sum(e['path'].startswith('content/workspace/') for e in m['entries']),'mismatches':problems,'mismatch_count':len(problems)},indent=2))
