import hashlib, json, os, stat, sys
m=json.load(open(sys.argv[1])); root=sys.argv[2]; problems=[]; count=0
for e in m['entries']:
 p=e['path']
 if not p.startswith('content/workspace/'): continue
 rel=p[len('content/workspace/'):]; full=os.path.join(root,rel); count+=1; kind=e['kind']
 if kind=='directory':
  if not os.path.isdir(full): problems.append((rel,'missing-or-not-directory')); continue
  if stat.S_IMODE(os.lstat(full).st_mode)!=e.get('mode'): problems.append((rel,'mode-mismatch'))
  continue
 if not os.path.lexists(full): problems.append((rel,'missing')); continue
 st=os.lstat(full)
 if kind=='symlink':
  if not stat.S_ISLNK(st.st_mode): problems.append((rel,'kind-changed')); continue
  data=os.fsencode(os.readlink(full))
 elif kind=='file':
  if not stat.S_ISREG(st.st_mode): problems.append((rel,'kind-changed')); continue
  if stat.S_IMODE(st.st_mode)!=e.get('mode'): problems.append((rel,'mode-mismatch'))
  if rel in {'.git/annex/keysdb/db','.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal'}: continue
  data=open(full,'rb').read()
 else: problems.append((rel,'unknown-kind')); continue
 if len(data)!=e.get('size',len(data)) or hashlib.sha256(data).hexdigest()!=e.get('sha256'): problems.append((rel,'content-mismatch'))
print(json.dumps({'workspace_entries_checked':count,'mismatches':problems,'mismatch_count':len(problems)},indent=2))
PY
